function auditFiniteReadout(get, codec, treeHash) {
  const source=JSON.parse(get("source-before.json"));
  const result=JSON.parse(get("finite-results.json"));
  const assert=(v,m)=>{if(!v)throw Error(m)};
  assert(get("source-before.json")===get("source-after.json"),"source map changed");
  assert(get("environment-before.json")===get("environment-after.json"),"environment changed");
  assert(get("test-temp-before.json")===get("test-temp-after.json"),"test root changed");
  const sha=s=>codec.sha256Latin1(codec.utf8Bytes(s));
  const entities=s=>s.replace(/&(#x[0-9A-Fa-f]+|#[0-9]+|amp|lt|gt|quot|apos);/g,(_,v)=>{
    if(v[0]==="#")return String.fromCodePoint(v[1]==="x"?parseInt(v.slice(2),16):parseInt(v.slice(1),10));
    return {amp:"&",lt:"<",gt:">",quot:'"',apos:"'"}[v];
  });
  const attrs=s=>{const a={};for(const m of s.matchAll(/([A-Za-z_][A-Za-z_0-9.-]*)="([^"]*)"/g)){
    assert(!(m[1] in a),"duplicate attribute");a[m[1]]=entities(m[2]);}return a;};
  const cohorts=[];let total=0;let phaseCount=0;let failureCount=0;let sourceOriginCount=0;
  for(const expected of result.cohorts){
    const name=expected.cohort;
    const cap=JSON.parse(get(name+"/pytest-capture.json"));
    const xml=get(name+"/junit.xml");
    assert(!/<!DOCTYPE|<!ENTITY|<!\[CDATA\[/.test(xml),"unexpected XML constructs");
    const suite=[...xml.matchAll(/<testsuite\s+([^>]+)>/g)];
    assert(suite.length===1,"exact suite");
    const sa=attrs(suite[0][1]);
    const cases=[...xml.matchAll(/<testcase\s+([^>]*?)(?:\/>|>([\s\S]*?)<\/testcase>)/g)].map(m=>({
      attributes:attrs(m[1]), outcome:/<(failure|error)\b/.test(m[2]||"")?"failed":/<skipped\b/.test(m[2]||"")?"skipped":"passed",
      body:m[2]||""
    }));
    assert(cap.collection_admitted===true&&cap.error===null,"collection admission");
    assert(cap.source_sha===source.source_sha&&cap.source_tree===source.source_tree,"capture source identity");
    assert(cases.length===Number(sa.tests)&&cases.length===cap.collection.length&&cases.length===expected.expected_cases,"actual case count");
    assert(cap.reports.length===cases.length*3,"three phases each");
    assert(new Set(cap.collection.map(r=>r.nodeid)).size===cases.length,"unique collected nodes");
    const seen=new Set();const phaseDistribution={passed:0,failed:0,skipped:0};const failures=[];
    for(let i=0;i<cases.length;i++){
      const row=cap.collection[i];const c=cases[i];
      const node=row.nodeid;const summary=expected.cases[i];
      assert(summary.nodeid===node&&JSON.stringify(summary.junit.attributes)===JSON.stringify(c.attributes),"JUnit exact row attributes/order");
      const params=node.indexOf("[");
      const head=params<0?node:node.slice(0,params);const tail=params<0?"":node.slice(params);
      const names=head.split("::");names[0]=names[0].replace(/\.py$/,"").replaceAll("/",".");
      assert(c.attributes.classname===names.slice(0,-1).join(".")&&c.attributes.name===names.at(-1)+tail,"independent ASCII JUnit address");
      const key=c.attributes.classname+"\0"+c.attributes.name;assert(!seen.has(key),"duplicate JUnit identity");seen.add(key);
      const phases=cap.reports.filter(p=>p.nodeid===node);
      assert(phases.map(p=>p.when).join(",")==="setup,call,teardown","actual phase order");
      for(const phase of phases){
        assert(phase.outcome in phaseDistribution&&!phase.wasxfail&&!phase.longrepr_censored,"phase outcome/censor");
        phaseDistribution[phase.outcome]++;
        const text=phase.longrepr||"";
        assert(codec.utf8Bytes(text).length===phase.longrepr_bytes&&sha(text)===phase.longrepr_sha256,"full traceback hash");
      }
      const outcome=phases.some(p=>p.outcome==="failed")?"failed":phases.some(p=>p.outcome==="skipped")?"skipped":"passed";
      assert(outcome===c.outcome&&summary.outcome===outcome,"case result bijection");
      if(outcome==="failed")failures.push({nodeid:node,phase:phases.find(p=>p.outcome==="failed").when,traceback:phases.find(p=>p.outcome==="failed").longrepr});
      assert(row.function.origin==="candidate"&&source.files[row.function.path].sha256===row.function.sha256,"test source hash");
      for(const list of Object.values(row.fixtures))for(const f of list){
        if(f.source.origin==="candidate")assert(source.files[f.source.path].sha256===f.source.sha256,"fixture source hash");
        assert(sha(cap.complete_definition_asts[f.source.complete_definition_ast_sha256])===f.source.complete_definition_ast_sha256,"fixture full AST hash");
      }
      assert(sha(cap.complete_definition_asts[row.function.complete_definition_ast_sha256])===row.function.complete_definition_ast_sha256,"test full AST hash");
    }
    assert(Number(sa.failures)+Number(sa.errors)===failures.length&&Number(sa.skipped)===0,"suite actual failures/skips");
    for(const row of Object.values(cap.source_origins)){assert(source.files[row.path]?.sha256===row.sha256,"loaded product origin");sourceOriginCount++;}
    for(const [hash,ast] of Object.entries(cap.complete_definition_asts))assert(hash===sha(ast),"all full AST hashes");
    assert(failures.length===expected.counts.failed&&cases.length-failures.length===expected.counts.passed,"reported counts");
    cohorts.push({cohort:name,cases:cases.length,passed:cases.length-failures.length,failed:failures.length,skipped:0,phases:phaseDistribution,complete_definition_asts:Object.keys(cap.complete_definition_asts).length,actual_source_origins:Object.keys(cap.source_origins).length,failed_cases:failures,all_cases:expected.cases});
    total+=cases.length;phaseCount+=cap.reports.length;failureCount+=failures.length;
  }
  const commands=JSON.parse(get("commands.json"));
  assert(get("commands.json")===get("steps.json"),"command ledger differs");
  for(const c of commands){assert(c.group_cleanup.passed===true&&c.group_cleanup.no_live_members_in_original_group===true,"owned group");
    const text=get(c.name+".log");assert(codec.utf8Bytes(text).length===c.log_bytes&&sha(text)===c.log_sha256,"command log");}
  const env=JSON.parse(get("environment-before.json"));
  const tree=treeHash(Object.entries(source.files).map(([path,v])=>({path,mode:v.mode,type:"blob",sha:v.git_blob})));
  assert(tree===source.source_tree,"complete source tree");
  return {audit_passed:true,original_workload_passed:false,source_sha:source.source_sha,source_tree:tree,harness_sha:source.harness_sha,source_files:Object.keys(source.files).length,harness_files:Object.keys(source.harness_files).length,actual_cases:total,passed:total-failureCount,failed:failureCount,skipped:0,incomplete:0,actual_phases:phaseCount,source_origins_checked:sourceOriginCount,cohorts,command_count:commands.length,failed_commands:commands.filter(c=>!c.passed).map(c=>c.name),all_owned_groups_retired:true,source_maps_equal:true,environment_maps_equal:true,test_root_equal:true,installed_versions:env.installed_count,all_versions_match_lock:env.all_versions_match_frozen_lock,scope:"Readout of original finite receipts only; no new project execution or qualification"};
}

